INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1051520-chem201', 'stk-user6687', 'CHEM 201', 'info', '{"desc": "كتاب ممتاز من كل النواحي\nيسلمونك كتابين (المقرر + سلوشن )\nاسئله كافيه وشرح ممتاز\n\nالماده تعتبر صعبة لأغلب الطلاب ويقوولون انها اصعب مادة في السفمور\nانا من رأيي إنها من أحلا المواد الي قد أخذتها وماتعبت فيها\n\nالسبب هو اني اخذتها مع دكتور موسى\nأغلب طلاب سكشنه كانت امورهم تمام ومرتاحين مع الماده\n\nاشوفها اسهل من الفزكس واسهل من كمستري 101 و 102 اذا فهمتها\nلان الفهم فيها أكثر من الحفظ والي يفهم شابتر 4 بيفهم المنهج كامل بالراحه\n\nانا انصح الطلاب الي ما قدرو ينزلون مع دكتور موسى انهم يحضرون في سكشنه للاستفاده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/3", "user": "user6687", "ts": 1338912179000, "tid": 120592, "pn": 3}}', 1338912179000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1092103-chem201', 'stk-chemistry.eng', 'CHEM 201', 'info', '{"desc": "تفضل الرابط :-\n\nhttp://www.4shared.com/rar/-UfRtQgm/Almullims_Slides.htmlمشكلة ادخال رابط خلف الكلام يحط الحروف في الرابط small letters\n\nوهو الموقع نفسه Case sensitive\n\nعلشان كذا يقولك الرابط متعطل 🙂\n\nومعليش على التأخير 🥰", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/9", "user": "Chemistry.Eng", "ts": 1347554378000, "tid": 120592, "pn": 9}}', 1347554378000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198561-chem201', 'stk-chemist', 'CHEM 201', 'info', '{"desc": "Chem 201 وما أدراك ما Chem 201\n\nالكتاب روعة + المانيوال سولوشن كافي وافي للمذاكرة\nهذي المادة عبارة عن الأشياء الأساسية في الكيمياء العضوية وتغطي الألكانات والألكينات والكحول والإيثرات و Free radicals reaction وSN1 & SN 2 Mechanisms وغيرها\n\nأنا بالنسبة لي أشوفها أصعب بكثير من Chem 202\nاحس انهم تعمقوا في دراسة Ch 4 يعني ندرس أشياء مفروض أنها للكيميائي مو للمهندس الكيميائي\nCh 4 & 5 من أصعب الشباتر\n\nالاب سهلات ماتطول فيه 🤴", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/12", "user": "Chemist", "ts": 1363046770000, "tid": 120592, "pn": 12}}', 1363046770000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316761-chem201', 'stk-guest', 'CHEM 201', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nأخذت المادة في سمستر 131 ، في هذا السمستر كان في كتابين للمادة سكشنين كانوا يستعملوا الكتاب القديم اللي هو fessenden and fessenden ، و ثلاث سكاشن كان تستعمل الكتاب الجديد اللي هو Macmurray 8th edition التقييم أدناه مبني على الكتاب الجديد، المادة تتكون من 15 تشابتر أول سكشنين كيمياء عامة بعدين تاخذ نظرة على المجموعات العضوية في التشابتر الثالث و بعدين تبدأ تدرس عدد منهم بالتفصيل في كل تشابتر ، في ميجرين كل واحد عليه 17.5 % و الفاينل عليه 28 % ، 12 % كلاس وورك و 25 % لاب، المياجر ريتن والفاينل 50 سؤال اختيارات ، الميجر الأول يعتبر سهل جدا جدا مقارنة بالثاني اياك تضيع الدرجات في الميجر الأول ، صحيح ان الميجر الثاني صعب بس يمديك لو ذاكرت من بدري وحليت الهوموورك بنفسك زي ما وضحت هذه أول سنة يستعملوا فيها هذا الكتاب فالبتالي أي أولد اكزام قبل سمستر 131 ما راح تفيدك بشي خلي مرجعك الرئيسي أسئلة الهوموورك تراها مفيدة جدا واللي يعتمد عليها ويحلها بنفسه من دون نقل من السلوشن يضمن قريد طيب باذن الله ، رفعت جميع كويزات الدكتور البطة على KFUPM RESOURCES أنصح بدراستها بعد ما تحل الهوموورك كاختبار لنفسك\n\nموفقين خير ان شاء الله 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/13", "user": "Guest", "ts": 1389109604000, "tid": 120592, "pn": 13}}', 1389109604000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420632-chem201', 'stk-medoalkebsi', 'CHEM 201', 'info', '{"desc": "جودة المقرر بشكل عام: المقرر عباره عن 15 شابتر .\nميجر 1, اول 5 شباتر وهي تعتبر مراجعه ومدخل للورقانك , وسهله جدآ ودايم افرج الميجر الاول عالي جدآ .\nالمجير الثاني من شابتر 6 الين 11 . والميجر هذا دسم ! يحتاج فهم + حفظ بشكل كبيييييير .\nالفاينل عباره عن المتيريل حق 1 و2 + شابتر 15 ,16,17,18 . هذي الشباتر اسهل من الي قبلها حق ميجر 2\nالكتاب المستخدم للمقرر : الكتاب ممتاز لكن مو زي حق 101 و 102\nالأسئلة والأمثلة المستخدمة في المقرر : االاسئله كثير ووافيه نهايه كل شابتر , الامثله نص ونص مو ذك الزود\n\nالكورس هذا اكثر كورس كمستري ابدع فيه , وحبيته اكثر من 101 و 102\n\nطبعا طريقتي للمذاكره كانت الكتاب بعدين احل الهومورك بنفسي انا وواحد من العيال ونتناقش فيه الين نفهمه 100%\n\nوكمان في الشباتر الطويله مثل شابت 8 , كنت احضره قبل الكلاس واسوي لي ملخص خاص فيني في ورق خارجي , اذا رحت الكلاس اركز مع الدكتور واكتب الملاحظات المهمه ع الورق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/18", "user": "Medoalkebsi", "ts": 1421684045000, "tid": 120592, "pn": 18}}', 1421684045000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439410-chem201', 'stk-user9534', 'CHEM 201', 'info', '{"desc": "الاورقانك وما أدرائك مالاورقانك 🙄\nكورس صعيب برشا 🤠 الزبدة نصيحة لوجه الله , اكتبها بماء الذهب : حاول قد ماتقدر تشد في الميجر الاول لانه سهل جدا مقارنة بالثاني … الثاني يارجل كورس لحاله 😦\n\nالمهم افعل الخطوات التالية :\n1- ذاكر الاولد اكزامز من 131 وأنت طالع لأن يجيبون نفس الأفكار (الاختبارات اللي أقدم للكتاب القديم ماراح تفيدك)\n\n2- موقع خان أكاديمي فادني وبقوة , يشرحون المنهج بشكل بسيط وسهل\nOrganic chemistry | Khan Academy\n\n3- القناة هذي باليوتيوب برضو مفيدة وفيها شروحات فادتني\nhttps://www.youtube.com/user/Leah4SciTutorials/featured\n\nواذا صعب عليك شي اكتب اسم التشابتر او السكشن باليوتيوب وبيطلع لك مقاطع بتساعدك وبقوة , لا تعتمد على مدرسك 😆\n\nوهذا رابط فيه : المانيوال سلوشن للكتاب 🙄 + الاولد اكزام للمنهج الجديد (131 وأنت طالع) 😎- + كويزات مفيدة للمراجعة 🌹\nchem201 - Download - 4shared\n\nان شاء الله اذا ضبطت ميجر ون وسويت الخطوات اللي فوق أضمن لك قريد طيب 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/19", "user": "user9534", "ts": 1453075748000, "tid": 120592, "pn": 19}}', 1453075748000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449946-chem201', 'stk-k_94', 'CHEM 201', 'info', '{"desc": "كورس غثيييييث وتشيل همه طول السمستر , يبغى له حفظ بشكل متعب جدا لولا الله ثم الاولد اكزام كان رحنا فيها\n\nركزززززز عالاولد اكزام يتكرر بنفس الافكار , لو انت صاحب حفظ فانت طحت بكورس ممتاز ,\n\nحاول تشد بميجر 1 لانه سهل مقارنة بالميجر الثاني , مياجر المادة رتن والفاينل mcq\n\nما اظن الصدق ان المدرس بيفرق في ذا المادة لانها تعتمد عالحفظ بشكل خرافي , لا تخرب جدولك فيها عشان مدرس اللكتشر , في اللاب حاول تجي مع واحد يخليكم تشتغلون بقروبات وتخلصون بسرعه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/20", "user": "K_94", "ts": 1463871117000, "tid": 120592, "pn": 20}}', 1463871117000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509878-chem201', 'stk-m7med_21', 'CHEM 201', 'info', '{"desc": "كورس صعب وطويل وثقيل ايضا لا شك\n\nلكنه بالنسبة لي اجمل كورس كيمستري درسته للان\n\nالكتاب ممتاز جدا\n\nالطريقة المثلى للدراسة :\nحل اسالة الكتاب كلها في السيلابس سؤال بسؤال كلهم مهمين\nحل اولد كويزز موجودة بالريسورس\nوقبل المياجر حل كل كل الاولد اكزام لانه متكرر\n\nاول ميجر اول خمس شباتر نوعا ما سهلة حاول تجيب فوق 90 بالمية\nثاني ميجر صراحة الشغل الجدي يبدا وصعب نوعا لكنه ليس مستحيل من بداية شابتر 8 التفاعلات تكثر سجلهم بورقة خارجية واحفظهم كلهم وصدقني بتلاقي متعة بحل الميكانزيم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/21", "user": "M7med_21", "ts": 1558246012000, "tid": 120592, "pn": 21}}', 1558246012000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1517673-chem201', 'stk-aomab', 'CHEM 201', 'info', '{"desc": "ترم 191\n\nقبل ما ادخل الكورس سمعت كلام كثير عن صعوبته وكيف انه كان سبب في خسف\nمعدلات بعض الطلاب\n\nالان منزله مع دكتور موسى ومقبلين على الفاينل واشوفه اسهل واكثر متعة من 101 و 102\nوتقديري اني اخرج بقريد اعلى منهم\n\nالكورس يحتاج فهم وحفظ ما تقدر تعتمد على الحفظ لحاله\nطبعا لازم تخصص ساعات معينة للمادة في الاسبوع من 3-5 ساعات مناسبة:\n1. تفهم الكونسبت\n2. تحل اسئلة الكتاب\n\nوفيه موقع راح يسهل عليك الكونسبت بشكل كبير\nOrganic Chemistry Syllabus Companion Topics List -\n\nوفالك A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/22", "user": "AOMAB", "ts": 1575649686000, "tid": 120592, "pn": 22}}', 1575649686000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533416-chem201', 'stk-user12136', 'CHEM 201', 'info', '{"desc": "اسمعني زين وهي نصيحة واحد وحطها حلقة بأذنك…(ادرس أول بأول)\nتعريف دراسة أول بأول: الي يشرحه الدكتور اليوم تدرسه وتفهمه و(تحفظه) اليوم\n\nالمادة دسمة جدا وتراك بتضيع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-organic-chemistry-i/120592/23", "user": "user12136", "ts": 1641984184000, "tid": 120592, "pn": 23}}', 1641984184000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1141938-chem201', 'stk-user6882', 'CHEM 201', 'info', '{"desc": "الاخ السائل لا تخاف وشد حيلك من الحين …وباالنسبة لدرجتك في ميجر 2 تأكد مليون في المية انه بسبب انك لم تفهم شابتر 5\"مفتاح النجاح في هذا الكورس\" جيدا لذلك انصحك ترجع وتذاكره مرة ثانية على النحو التالي :\nاقرا سلايدات المعلم - حل الامثلة -حل اسئلة نهاية الشاتبر - راجع حللول الكويزات\nواذا اشكل عليك شيئ روح للدكتور في الاوفيس\nواذا طبقت اللي فوق والله يمكنك تجيب بي او بي بلس لان المياجر نسبتها قليلة بالنسبة للفاينل\nوترى المادة هذي يغتر كثير من الطلاب فيها ويفكرها نفس الكميستري السابقة يوم او يومين يكفيها لكن الحقيقة يبغالها اقل شي عشرة ايام قبل اي اختبار …وبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem201/136018/13", "user": "user6882", "ts": 1355588150000, "tid": 136018, "pn": 13}}', 1355588150000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466948-chem201', 'stk-user9948', 'CHEM 201', 'info', '{"desc": "انا سألت دكتور موسى موسى عن طريقتهم لتوزيع القريدات في chem201 وقالي بعد الفاينل يحسبون درجات جميع الطلاب من ١٠٠ وبعد ذالك يرتبون الطلاب من اعلى واحد الى انزل واحد\nومن هنا يوزعون القريدات بنسب معينة بين الطلاب\nوعلمني ان standard deviation دائما يفرق بين الطلاب فمستحيل تحصل طالبين نفس المجموع فبذالك مافي شي اسمه upgrade\nوهذا كل مالدي وبالتوفيق في الكورسات الجاية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201/175836/7", "user": "user9948", "ts": 1485296541000, "tid": 175836, "pn": 7}}', 1485296541000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p889759-chem201', 'stk-user3356', 'CHEM 201', 'info', '{"desc": "CHE\n\nافضل المدرسين : ابو السعود … و باشماخ\nالمادة سهله … تتكلم عن الماس بلنس و الانيرجي بلنس\nافضل طريقة للمذاكرة نوت المدرس و الكتاب\n\nME 205\nافضل مدرس : العقيلي\nالمادة حلوة نوعاا ماا … تتكلم عن خواص المواد و طبيعتها\nافضل طريقة طريقة للمذاكرة سلايدات المدرس و ركز ع الاولد اقزام\n\nChem 201\nالمعلم ممتاز\nالمادة غثيثه نوعا ما و المنهج طويل و متشابه … يتكلم عن الكيمياء العضوية\nالكتاب كويس بس شارح كل شي بالتفصيل … السلايدات كويسه بعد\n\nالماث\nانا درست مع اسان لو مدرس ممتاز جدا بس عيبه اللهجه\nالمادة سهلة شوية تركيز بالكلاس و تمشي الامور تتكلم عن الهندسة الفراغيه و الثري دايمنشن\nعليك بنوت المدرس\n\nو بالتوفيق لكـ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/111043/2", "user": "user3356", "ts": 1313978783000, "tid": 111043, "pn": 2}}', 1313978783000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p59079-chem201', 'stk-user439', 'CHEM 201', 'info', '{"desc": "اهلين بالمتفاءل\n\nبالنسبه لمادة CHEM201\n\nالماده ماده حفظ 100% و نسبة الفهم تكاد ان تكون معدومه\n\nالمياجر القديمه لها كثيره ومتنوعه وانا راح احاول تضبيطها في ملف واحطها في المنتدى\n\nوبالنسبه للماده CHE201\n\nالماده مهضومه وسهله واسئلتها حلوه في المياجر بس طويله شوي\n\nالوقت يا دوووب يسعفك ولكن ترى الوقت عليك وعلى غيرك\n\nالماده ماده فهم 95% واما 5% في عباره عن حفظ ا standard معين وبعض المعادلات الخفيفه\n\nولازم تفهم شغلة مهمه وهي كيفية التوصل الى العلاقات مثلا\n\nكثافة السائل هل تزيد ام تنقص مع\n1-ارتفاع الحراره\n2-ارتفاع الضغط\n3- تغير الMw\n4- تفير ال flow\n\nفهم هذه العلاقات ترسخ المعلومات في ذاكرتك وتنمي حاجه عندك يسمونها\nengineering sense\n\nولاي استفسار انا موجود", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/39998/2", "user": "user439", "ts": 1095497027000, "tid": 39998, "pn": 2}}', 1095497027000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518571-chem201', 'stk-m.tawhari', 'CHEM 201', 'srcP', '{"html": "ملفات اولد اقزام باي شابتر كيمياء عضوية (كمستري 201)<br><br>​<span data-fid=\"stk-f1518571-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1518571-0": {"name": "Organic_old.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d2dc6b350bd6bd93f824b79892a98a429db0b03adfc79263b2615c07184de16d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/organic-chemistry-chem-201-old-exam-by-chapter/182517/1", "user": "m.tawhari", "ts": 1577883554000, "tid": 182517, "pn": 1}}', 1577883554000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
