INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1092470-chem201', 'stk-king_of_net', 'CHEM 201', 'srcU', '{"html": "تفضل يالطيب<br><br>السلابس حقت اللكتشر واللاب<br><br>​<span data-fid=\"stk-f1092470-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1092470-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1092470-0": {"name": "121-201-Lec_Syllabus.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7d20f87fc7b085c6e06d5b84bcc22be70ed22bc15d06e8aee5114ff63ec94fbc"}, "stk-f1092470-1": {"name": "121-201-Lab syllabus.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-syllabus/131853/2", "user": "KinG_OF_NeT", "ts": 1347620527000, "tid": 131853, "pn": 2}}', 1347620527000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p803141-chem201', 'stk-_0014', 'CHEM 201', 'srcU', '{"html": "في المرفقات<br><br>بالتوفيق<br><br>​<span data-fid=\"stk-f803141-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f803141-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f803141-0": {"name": "102-201-Lec_Syllabus.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fc9522a6e2473af721deeec1d7f14848a87cc31e932527783941ec04c7226a82"}, "stk-f803141-1": {"name": "102-201-Lab syllabus.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-201-syllabus/103837/2", "user": "_0014", "ts": 1298965535000, "tid": 103837, "pn": 2}}', 1298965535000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p949732-chem201', 'stk-abu_mnahe', 'CHEM 201', 'srcP', '{"html": "تفضل عزيزي<br><br>​<span data-fid=\"stk-f949732-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f949732-0": {"name": "Solution_CHEM-201_Second_Maj-111.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/6c0d380e4e6c40646493b0649bfadea7bda253d2604c89431b90f1b11973c716"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chemistry-201-second-major/116720/3", "user": "ABU_MNAHE", "ts": 1324250874000, "tid": 116720, "pn": 3}}', 1324250874000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_sad_story-chem201', 'stk-the_sad_story', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "محمد صديقي Chem 201 - Term 123\n\nبنود التقييم :\n\nالتحضير : ورقة تمر بين الطلاب بشكل يومي، يقفط إذا أحد محضر خويه !!\n\nطريقة الشرح : تختلف\nبعض الأحيان ( خاصة بداية الكورس ) يكون على السلايد ويوقف عند نقطة معينة ويشرحها على السبورة بشكل مفصل، بس على آخر الكورس صار يشرح أول 20-30 د الأفكار بشكل سريع نوعاً ما على السبورة وباقي الوقت يشغل السلايد ويعيد الكلام اللي قاله ( أنصحك ما تتأخر على الكلاس لأن إذا فوت أول عشر دقائق ، راح تفوت كثير من الأفكار وراح تشوفه كأنه مستعجل ويبي يمشي السلايدات !! )\n+\nأيضًا الرجل متجاوب مع الطلاب بشكل كبيييير جداً في الكلاس، الرجال من ثاني أو ثالث أسبوع عرف أسامينا ، ويقطع الشرح إذا فيه سؤال ، يخلي الطلاب يشاركون و يتقصد الطالب المهمل بالأسئلة، نكتــي من طراز أول ، ياخذ من الكلاس دقيقة أو إثنتين يعطي نصائح ويشارك تجارب سابقة له…\n\nالكويزات :إختبرنا تقريباً 9 إختبارات !!! حذف فيها أسوء إثنين ، وبالنسبة لي أشوف مستواها متوسط.\n\nالمياجر: كــومن\nالفاينلات :كـــومن\nالقريد النهائي: A++++++++++++++++++++++++++++++++++++++++++\nالصوت:ممتار ، ما أتذكر إني كنت أعاني من درجة الصوت أو الأكسينت !!\n\nإضافات :\nأفضل دكتــور في الجامعة بالنسبة لي، و العلاقة اللي يبنيها مع الطالب جداً مهنية و مفيدة في حياتك في الجامعة أو خارجها. راح ترتاح له كثير إذا ركزت معه في الكلاس ( طبعاً نصيحة المادة زي ما يقول الدكتور You Can’t skip the hard work ، يعني مهما كان الدكتور مبدع فلازم أنك ترجع وتذاكر أول بأول التفاعلات وطرقها المختلفة)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1243141-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/27", "user": "the_sad_story", "ts": 1373157703000, "tid": 68459, "pn": 27}}]}', 1373157703000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupm_knight1-chem201', 'stk-kfupm_knight1', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم شباب\nأنا أخذت مع المدرس هذا في ترم 102 مادة CHEM 201 وأخذت معاه اللاب كمان.\n\nالتحضير: ينادي بالأسماء في كل حصة تقريبا\n2.طريقة الشرح: يستخدم السلايدات والسبورة. المدرس يشرح المفاهيم بشكل واضح جدا للمادة. يعني من ناحية الكونسبت حتكون مية مية. لكن المشكلة انه الكيمياء مهي بس مفهوم, هي فيها حفظ كمان. فإذا أخذت معاه chem 201 فاستعد للكرف في هذي المادة, واعني كل معاني الكرف من مذاكرة اسبوعية وتجي الساعات المكتبية عشان تجيب اذا كنت ناوي تاخذ A في المادة.\n\nالكويزات: بشكل أسبوعي والأسئلة اللي يجيبها لازم يكون فيها لفتين شوية. ما يحب يجيب أسئلة مرة سهلة ولا مرة صعبة.\n\nالمياجر: كومن\n\nالقريد النهائي: A إلى B+ للي يحب ياخذ المادة بجدية للأنه المدرس متمكن جدا وعنده شهادتين دكتوراه.\n\nالصوت: واضح وانجليزية جيده\n\nإضافات: المدرس يقدر اللي يجيه في الساعات المكتبية واذا الدكتور عرفك انك شاطر وشاد حيلك فأبشر انه حيساعدك. والدكتور تقدر تجيه في مكتبه حتى في الليل. وهو كمان ما يحب التساهل واللا مبالاة من الطلاب في الفصل. إذا حاولت بس تقول كلمة لصاحبك وقت الشرح يقلك:\nHey! what are you doing? get serious!\n\nومن ناحية اللاب\nفأنا أنصح الطلاب ياخذوا معاه لأنه في اللاب مرة حبيب ويتكلم ويضحك معاك, و لو عندك سؤال يجاوبك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p936685-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/25", "user": "KFUPM_KNIGHT1", "ts": 1322181222000, "tid": 68460, "pn": 25}}]}', 1322181222000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_1148-chem201', 'stk-_1148', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 201 term111\n\nالتحضير :كان يحضر اخر الكلاس واصلا كان حافظنا لا السكشن حقنا كان ١٥ طالب بس\nطريقة الشرح :يشرح على السبورة ويوضح احيانا على السلايدات اذا احتاج الامر\nالكويزات :كثيييييييييرة وطويييييلة ، على كل تشابتر فيه كويز واحد على اقل تقدير\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت:واضح بس اللكنة هندية بس مقبولة جدا جدا\nإضافات :\n\nالزبدة اللي يبي ياخذ الاورجانيك ويشد حيله فيها وناوي يكرف ويذاكر ، الدكتور نصار الله هو الرجال المناسب لك\n\nالرجال يعطي واجبات كثييرة مع ان الكورس ما فيه واجبات وكويزات باستمرار وكلها تفيدك بالمياجر\n\nمن كثر الواجبات والكويزات ، قبل الفاينل بيوم بس قريت الواجبات والكويزات وطلعت بدرجة حلوة ، طبعا هو ينزل الحلول في الويب سيتي\n\nبس اذا ناوي تاخذ المادة وتهملها فنصار الله غير مناسب لك لانه بيهزئك على الطالعة والنازلة ، ليش ما سلمت الهوموورك وليش ما تنتبه الخ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970912-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/27", "user": "_1148", "ts": 1326983989000, "tid": 68460, "pn": 27}}]}', 1326983989000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moha-chem201', 'stk-moha', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 172\nالمادة: CHEM201\n\nالتحضير: تحضير بكل كلاس عن طريق تمرير ورقة ويخصم درجة في الكلاس وورك عن كل غياب\nطريقة الشرح : متيريل ميجر 1 كان سهل فما كان يحتاج دكتور يكون جيد عشان يشرحة او يوصل المعلومة لكن بعد ذلك في متيريل ميجر 2 والفاينل ماكان أحد فاهم وش قاعد يقول و يقول أشياء مو مهمة بوسط الشرح وبعدين يقول ( This is not your level) باختصار شرحة لمتيريل ميجر 2 والفاينل سيء جدا بالاضافة الى انه شرحه سريييع جدا\nعنده اسلوب تشتيت انتباه اثناء الكلاس مو طبيعي مثلا فجاه يوقف شرح ويتكلم عن انجازاته وممكن يقطع الشرح فجاة ويقعد يسفل بطالب حتى لو ما سوا شيء يسوا\nالكويزات :عطانا 5 كوزات و 10 هوومووركات اغلب الهوومووركات طويلة ووزنها بالكلاس وورك جدا قليل باختصار اهم شيء الكوزات\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:F واحسها واجدة عليه\nالصوت: جيد\nإضافات : 1-الاسلوب اللي تعامل فيه مع الطلاب غير مقبول بتاتا وممكن يرفع صوته على طالب وسط الكلاس ويسفل فيه قدام الطلاب باتفه الاسباب لدرجة انه اسوء واحد درسني خلال 15 سنة من حيث الاخلاق والاسلوب الرخيص\n2- ما يحترم الطلاب ولا البيئة التعليمية اللي موجود فيها وممكن يسب او يقول الفاظ غير مناسبة وايضا اي اتصال يجيه يقطع الشرح ويرد وهذا يتكرر بشكل دائم!!!\n3-محاولة التاثير ع الطلاب بالافالويشن بحيث يقول ان الافالويشن (لتقييم المادة) فقط وانه (أنا) التشيرمن حق الافالويشن وانه ما فيه فايدة اذا كتبتو تعليق عني …طبعا يوم سألت رئيس القسم عشان اتاكد من المعلومة طلع مو هو التشيرمن ولا شيء من ذا الكلام\n4- اذا حقد عليك الله يعينك لانه يشخصن الامور بشكل مو طبيعي وبيصير يركز عليك وسط الكلاس ويسفل فيك قدام زملائك\n5-تقييمه بالموقع ممتاز لكن يوم نزلنا معه انا وزملائي انصعقنا باسلوبه المتعجرف الرخيص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492662-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/30", "user": "MOHA", "ts": 1526619709000, "tid": 68460, "pn": 30}}]}', 1526619709000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.a-chem201', 'stk-m.a', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 181 CHEM 201\n\nفي اللاب واللكتشر\nفي اللاب:\nالكويزات تيجي من الأوراق اللي يعطيك حق التجربة، ويطلعك بدري إذا خلصت أو كان عندك إختبار والطالب يجب عليه أن يركز إذا كانت التجربة فردية أو إثنين مع بعض لأنه أي طالب يخالف كلامه ويسوي الفردية مع واحد ثاني يخليه يعيد التجربة لحاله، ودرجات الطلاب في اللاب تعتمد أكثر شيء على الكويزات لأنه في الأخير بيصير نورمالزيشين للدرجات ودرجات الطلاب تطيح الي ما جابوا زين في الكويزات حقت اللاب، علماً أن عددها أربعة كويزات فقط.\nإضافات على الدكتور في اللاب:\nالدكتور يحب الصدق في كل شيء، مثلاً في نتائج التجربة إذا طلعت النتيجة النهائية للتجربة قليلة إكتب له سبب الخطأ في الورقة ويحسبها لك.\nاللكتشر:\nالتحضير :\nورقة تمر على الطلاب، وبعض الأحيان يحضر بنفسه على نهاية الترم بعد ما يحفظ أسماء الطلاب.\n\nطريقة الشرح :\nسلايدات + سبورة\n\nالكويزات :\nصعبة للي مايذاكر + هومووركات هو يعملها بنفس مستوى الكويزات، والكويزات تيجي بعضها من الهومووركات.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+++++\n\nالصوت:\nممتاز ، آكسنت هندية لكنها أفضل بمراحل من غيره\n\nإضافات :\nيكره شيْ إسمه جوال في يد الطالب، لأنه يلهي الطالب عن التركيز معه ويأخذ على الطالب ملاحظة لأنه طلع الجوال.\nوإذا كنت تيجي المكتب وتسأله و حس أنك مهتم يضبطك في الدرجات النهائية، ويهتم مرة بالحضور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504611-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/31", "user": "M.A", "ts": 1546837557000, "tid": 68460, "pn": 31}}]}', 1546837557000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-neran-chem201', 'stk-neran', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68460", "n": "Dr. Nisar Ullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 Lecture and Lab Term 181\nاللكتشر\nالتحضير:\nورقه كان يمرره على الطلاب واحيانا يحضر بنفسه وراح يكون حافظ اسماء كل اللي في السكشن بعد فتره قصيره\n\nطريقة الشرح:\nيستخدم السلايدات شرحه ممتاز لكن في ماتيريل الميجر الثاني صرت ما افهم وش يقول ابدا واعتقد هالشئ بسبب صعوية الماتيريل وان اغلبها حفظ\nالكويزات:\nكوزاته اشوفها سهله لأنه يجيب نفس افكار الهورمورك واحيانا يجيب نفس اسئلة الهورمورك بالضبط لذلك افهم الهومورك وان شاء الله الكوزات راح تكون مضمونه.\n\nالمياجر:\n-ميجرين الاول جدا سهل الافرج كان 76 والثاني راح يكون صعب بحكم ان الماتيريل صعبه لذلك الاول راح يكون فرصه لك لاتضيعها\n\nالفاينل:\n- الفاينل كان صعب مع انه كان خيارات وهالشئ راح يغنيك عن الحفظ لكن كان مليان تريكات\n\nالصوت:\n- في بداية الترم كان صعب علي فهمه بحكم انه يتكلم بسرعه وبلهجه هنديه لكن بعد كم اسبوع تعودت عليه.\n\nالمختبر:\n- كان ممتاز جدا في اللاب يشرح خطوات التجربه بالتفصيل في بداية اللاب ثم عاد يطلع ويخلينا نشتغل على راحتنا وتقريبا كل ربع او ثلث ساعه يجي يشوف اذا ماشين او صح ايضا اغلب الوقت كنا نخلص 3 يعني ناخذ ساعتين في اللاب فقط\nالكوزات كانت اربع كوزات اذا ركزت معه في الشرح والخطوات وذاكرت الورقه اللي يوزعها عليك راح تضمن درجه طيبه في الكوزات وهي اللي راح تحدد قريدك في اللاب بحكم انه في الريبورت مايعطي احد اقل من 90\n\nإضافات:\n- .افرج كلاسه في الميجر الاول والثاني والفاينل كان اعلى من افرج الكورس ب 10 نسب وهذا شئ كبير\n\n- اغلب الوقت في مكتبه تقدر تجيه في اي وقت وبدون موعد.\n\n- ايضا الدكتور جدا طيب مع الطلاب ويحب يساعدهم لكن ايضا شديد في الكلاس جدا انتبه تطلع جوالك في الكلاس او حتى ماتركز معه راح يفصل عليك.\n\n- بختصار اذا شفت اسمه نزل عنده.\n\nالقريد النهائي:\nA+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504646-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nisar-ullah/68460/32", "user": "neran", "ts": 1546868703000, "tid": 68460, "pn": 32}}]}', 1546868703000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tiger7-chem201', 'stk-tiger7', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68482", "n": "Dr. Shaikh Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 - SEMESTER 151\n\nالتحضير : يوميا ورقة تمر على الطلاب\nطريقة الشرح :شرح ممتاز، يكتب اللكتشر على السبورة ، شغل مرتب ويحاول انه مايمسح حق الي يبي يصور 🚬\nالكويزات :متوسطة مائلة إلى الصعوبة\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت: واضح (اكسنت هندي)\nإضافات :\nانصح به جدا لأن الدكتور فاهم جدا وراح تستفيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437749-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-ali/68482/14", "user": "tiger7", "ts": 1451731063000, "tid": 68482, "pn": 14}}]}', 1451731063000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4625-chem201', 'stk-user4625', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68484", "n": "Dr. Bassam El-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nاول مايبدا الكلاس يتواسى ع الكرررسي ويحضر\nطريقة الشرح :\nبعض المرات سلايدز وبعض المرات يشرررح ع السبووره … بس شررريح بمعنى الكلمه … مايكتب نووت ويفضل تجيب معك الكتاب عشان تمشي معه ع نفس الشررح … لان تقريبا اغلب الامثله اللي يشرحها من الكتاب\nالكويزات :\nبعد نهاية كل شابتر ع طوول الكلاس اللي بعده كوويز … اذا مذاكر بتحله … لانه مو صعب ابد … وبعد مايصحح الكويز يرجعه لكم مره ثانيه … ويطلبه منكم تسلموونه ع اسااس هوموورك … صلح اخطاائك وارجع سلمه مره ثانيه\nالمياجر:\nكوومن\nالفاينلات :\nكومن\nالقريد النهائي: A+\nالصوت:\nمررره واضح\nإضافات :\nالدكتوور مرره محتررم ويرحب بااي سؤال … من بداية الكلاس تحس براحة نفسسيه من الشخص اللي قدامك … ويحب الخير لطلابه ينصحهم بعد كل كويز وميجر يحااول باي طريقه يخلينا نهتم بالماده ونعطيها حقها …هالكلام كله chem201 ‘101’", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p839279-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bassam-el-ali/68484/9", "user": "user4625", "ts": 1304211576000, "tid": 68484, "pn": 9}}]}', 1304211576000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12136-chem201', 'stk-user12136', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68484", "n": "Dr. Bassam El-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem201 term 211\n\n-التحضير : يأخذ التحضير نهاية كل حصة ومتساهل في التأخير مدة 5 دقائق تقريباً ونادراً ما ينسى التحضير\n\n- طريقة الشرح : والله أمانة الدكتور جداً جدأ فاهم المادة وهو جداً عبقري تبارك الرحمن، بس ما اجوف مستوى الشرح اسطوري، اجوفه جيد مائل إلى جيد جداً، شرحه يعتبر سريع ودايماً في باله ان كل الطلاب فاهمين يعني الحموز وموسى موسى أفضل في الشرح حسب كلام الشباب.\n\n-المياجر: Common\n-الفاينلات : Common\n\nالكوزات: جلللللدددد من الزين، والله صعبة صعبة صعبة!! ولكن مفيدة جدا للمياجر والفاينل\n\n-القريد النهائي: B+\n\n-الصوت: واضح جدا، ولغة الدكتور متقنة وواضحة.\n\n-إضافات :\nالدكتور متفهم جدا مع جميع الطلاب. ومحب جدا لمادته. يرحب بالطلاب في الساعات المكتبية وهي مفيدة جداً، خلوق ومتواضع وحبيب، كان كثير يساعدنا بتأجيل الكوزات ومناقشة المواعيد.\nوطبعاً انسى شي اسمه اوف، مستحيييل يعطي اوف بعد المياجر او حتى يحول الدرس اونلاين. وكذلك يعيب الدكتور ان يركز عالطلاب الشطار ويوترهم بشكل مو طبيعي، دايم يسألهم إذا يعرفون او لا ويعاتبهم اذا نقصوا في الكوزات وكذا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533410-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bassam-el-ali/68484/14", "user": "user12136", "ts": 1641982331000, "tid": 68484, "pn": 14}}]}', 1641982331000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmxd-chem201', 'stk-ahmxd', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68484", "n": "Dr. Bassam El-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 - Term 221\n\nالتحضير : يحضر بداية الكلاس ومتساهل مع التاخير, ترمنا اعطى غيابين بدون خصم\nطريقة الشرح : يعرض سلايداته ويشرح منها , فيها امثله ممتازه تفتح عقلك للدرس\nالكويزات : كويزاته نصها اختيارات ونصها ريتن , مستواها صعب لكن تجهزك للمياجر وفيه كم سوال من كويزاته جت بالفاينل\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A مشكلته الوحيده شرحه شوي سريع\nالصوت: واضح\nإضافات : انا عني حبيته مره شخص فااااهم وله خلفيه كبيره بالindustrial chem الشي الي بيفيدك بذا الكورس\n\nفالكم ال A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536232-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bassam-el-ali/68484/15", "user": "Ahmxd", "ts": 1674395678000, "tid": 68484, "pn": 15}}]}', 1674395678000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-chem201', 'stk-user4988', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68549", "n": "د. هيرمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "101\nchem 201\nليكتشر …\n\nالتحضير : ينادي بالأسماء … و يركز في التحضير !!\n\nطريقة الشرح : ممتازة جداً\n\nالكويزات : كويزات هيرمان هي أحد أسباب كره الطالب لشيء اسمه كويز مستقبلاً !!\n\nالمياجر:كومن …\n\nالفاينلات :كومن …\n\nالقريد النهائي: أنا أعطيه B+\n\nالصوت: أكسنت أمريكي خالص … و واضح !!\n\nإضافات :\nالرجال كويس و ما عليه كلام و سلايداته ممتازة … لكن الأخ فيه عدة سلبيات :\n\n1 - كويزاته … و ما أدراك ما كويزاته … كثيرة + أحيانأ تجيك طويلة او فيها لفلفة تكره حياتك بعدها !!\n\n2 - و هو الأهم … تصحيحه سواءً في الكويز أو في الميجر … تحس إن في رأسه وسوسة …خاصةً في الأسئلة اللي اجابتها تكون كتابية - يعني تجاوب ليش المركب السيني يتفاعل أسرع من الصادي - … لازم تكتب الجواب اللي في رأسه هو … و إلا ما تشوف إلا إكس أحمر … و أحياناً إذا إنك جاوبت صح لكنك كتبت خطأ بسيط … تلقاه حاط على الجواب كله إكس … سلامات !!!!!! أتعب في كتابة الجواب … آخرتها يساويني باللي ترك السؤال أبيض !!!!\n\nبأعطي معلومة صغيرة … لما تستلم نتيجة الميجر حقكك … و تلقى أحد المصححين استخدم قلم أحمر خشبي - يعني ما استخدم قلم الحبر - … فأعرف إنه هو اللي صحح هذا السؤال !!!!!\n\nختاماً الرجال ممتاز … لكن ادعي ربك إنه ما يصحح لك الميجر و إلا ما تشوف إلا النور بعدها !!!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p761034-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68549/12", "user": "user4988", "ts": 1294663616000, "tid": 68549, "pn": 12}}]}', 1294663616000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-chem201', 'stk-chemist', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f68549", "n": "د. هيرمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه chem 201 ترم 101\nالتحضير:\nكل يوم بس مايدقق كثير على التأخير\n\nطريقة الشرح:\nبطل في الشرح يشرح لك المنهج بطريقه مشوقه بس بعض الاحيان مايركز على بعض الاشياء\nالهامه ومايعطي عليها امثله كثيرة\n\nالكويزات:\nكثيييييييييييييييييييييييييييييرة لاتستغرب كويزين اسبوع واحد 🥊اجل معطينا كويز اول يوم في\nالدراسه بعد الاجازه بس تراها لصالحك ومالومك اذا اغتثيت وكل كويز عليه واجب اختياري و\nهو انك تصحح حلك وبعدين يجمع درجه الواجب مع درجه الكويز وتكون هذه درجه الكويز اللي اخذته\n\nالمياجر والفاينل:\nكومن\n\nالاضافات:\n1) مثل ماتفضل اخوي “أبو مرسمة !!” تصحيحه في الماجر كويس بس بلاه في الاسئله الرتن\nاعتقد مهما تكتب ماينظر الا الى الاجابه النموذجيه الموجوده عنده\n2) سلايداته كوبي بيست من الكتاب بل هي الكتاب نفسه لاتغير\n3) الدكتور اخلاق ومحترم وماعليه كلام\n\nالقريد النهائي:\n+B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p788207-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68549/13", "user": "Chemist", "ts": 1297579771000, "tid": 68549, "pn": 13}}, {"id": "stk-dr-f81012", "n": "Dr. Mohammad Al-Imam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 201 & 202 LABS Term 101 &102\n\nالتحضير:\nمن خلال الريبورت ولا يحاسب على التأخير غالبا\n\nالشرح:\nممتاز جدا يختصر لك الطريقة ويعطيك الزبدة ولكن في بعض الأحيان وخاصة في 202 يقول لك انت سوى التجربة من خلال قرائتك وفهمك ولا يشرح الا الأشياء الصعبة\n\nالكوزات:\nمافيه\n\nاضافات:\n1) كن مانطول في اللاب ساعتين بالكثير واحنا خالصين\n2) اخلاقه حلوة مستعد يجاوب لك على اي سؤال ومايحب انك سوي شئ وانت مافهته فيقعد يشرح لك الين تفهم\n3) مايدقق كثير على الطلاب فتقدر تاخذ الداتا من اي طالب اخر وتقول انك سويت التجربة وهو لادرى عنك ولا شئ\n4) تصحيحه مو بطل مره بس كويس يعني فيه بعض الحاجات يدق عليها كثير بس مازلت ارى ان تصحيحه حقاني وكويس\n5) ارتحت له كثير فأخذت معه لابين اورقانيك\n\nالقريد النهائي:\n+B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044070-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-imam/81012/24", "user": "Chemist", "ts": 1337902204000, "tid": 81012, "pn": 24}}]}', 1297579771000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-chem201', 'stk-k_94', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f118613", "n": "Dr. Ahsan Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 152\nCHEM201 لكتشر …\n\nالدكتور شرحه كويس ودائما يهتم بايصال المعلومة ويشجعك تحضر الاوفيس عنده , كوزاته تقريبا نفس اسئلة الهوموورك , لو جا وقت الكوز والطلاب طلبوا التاجيل ياجل ما عنده مشكلة يقول ما في فايده اعطي كوز ومنتم جاهزين\n\nمشكلته لازم يعطيك ملخص عن الدرس نهاية المحاضره ومعظم الاحيان ياخذ فوق وقته\n\nالدكتور متسامح في قضية التاخير وللاسف بعض الطلاب استغلوا الوضع بكل وقاحه يدخل اخر 10-15 دقيقه عشان التحضير\n\nالقريد النهائي B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449947-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahsan-qureshi/118613/10", "user": "K_94", "ts": 1463871535000, "tid": 118613, "pn": 10}}, {"id": "stk-dr-f81690", "n": "Dr. Musa Musa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب CHEM 201\n\nTerm 152\nالتحضير : يحضر عن طريق الريبورت اللي تسلمه\n\nطريقة الشرح :\nالدكتور متمكن جدا من الاورجانك وفاهم باللاب ولكن انت باللاب تبي واحد يمشيك بسرعه ما يفصل لك بالكورس\n\nالكويزات :\n5 كوزات وحذف واحد ( اجباري من القسم اقل شي4 كوزات باللاب )\n\nالدكتور فلاوي وراعي سوالف والقعده معه جدا جميله ولكن ما انصح فيه باللاب ابدا لانه يرفض العمل بمجموعات الا اذا تطلبت التجربة بسبب نقص الادوات\n\nكنا دائما نقعد لاخر الوقت واللاب غثيث خلقه والدكتور يطوله بزياده\n\nمن رأيي انك تسجل عنده باللكتشر وتنحاش باللاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449948-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/musa-musa/81690/17", "user": "K_94", "ts": 1463871886000, "tid": 81690, "pn": 17}}]}', 1463871535000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-chem201', 'stk-aomab', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f81690", "n": "Dr. Musa Musa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 191-(CHEM201(Lab+Lecture الدكتور موسى^2(اسطورة الكيمياء العضوية)\n\nالتحضير :\n1. يحضر كل الكلاسات\n2. التحضير بورقة تلف على الكلاس\n3. سمح بالتأخير (بس لا تزودها)\n4. يحذف غيابين اخر الترم\n5. ما فيه ايام اوف بعد المياجر\nطريقة الشرح : الشرح افضل شرح شفته في حياتي\nيستخدم السبورة(نصيحة اللي يبي A+ يصورها لانها تعتبر كنز)\nالمعلومات اللي يذكرها وما يكتبها سجلها في النوته\nالكويزات : متوسطة مايلة للصعوبة (بمستوى الميجر)\nاذا نزل الافرج ممكن يسهلها\nالمياجر: كومن (الميجر يجي من شرحه)\nالفاينلات : كومن\nالقريد النهائي: A+++++++++++\nالصوت: واضح جدا\nإضافات :\nاللي ينزل عنده يعتبر منزل عند احسن دكتور organic\n(بدليل افرجه اعلى افرج) مستحيل تجيب اقل من الافرج\nاذا اتبعت نصايحه\nالدكتور من النوع اللي يسوي كل شيء عشان الطالب يفهم\nممكن يشرح المعلومة عشرين مرة عشان تفهم\n\nنصيحة اخيرة شرح الدكتور لحالة ما يكفي المادة تحتاج تدريب بشكل شبه يومي\nاسئلة الكتاب مفيدة جدا+ الاختبارات القديمة+ كوزات الدكتور راح انزلها ان شاء الله في الريسورسيز\n\nعذرا على وفالكم A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517609-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/musa-musa/81690/21", "user": "AOMAB", "ts": 1575451827000, "tid": 81690, "pn": 21}}]}', 1575451827000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-chem201', 'stk-ahmed1', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f81690", "n": "Dr. Musa Musa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 201 (Lec) - Term 212\n\nالتحضير : ورقة تمر على الكلاس وما يحب تحضر نفسك وتطلع برا، فيعني ماله وقت محدد في حق التحضير، يعطيك غيابين فري وما يكنسل ولا كلاس حتى اللي بعد الميجر.\n\nطريقة الشرح : شرحه اسطوري اسطوري اسطوري، افضل دكتور كمستري درست عنده، لو تفهم من شرحه وتذاكر السبورة اللي يعيبها كل كلاس، امورك بتصير حيل طيبة وما راح تتعب في المادة واجد.\n\nالكويزات : كويزاته مستواها متوسط بشكل عام، احيانا تصير سهلة واحيانا يصعبها شوي بس غالبا مستواها حلو.\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A+++++++++++++++++++++\nالصوت: واضح جدا ولغته ممتازة\nإضافات : الدكتور اتعب وانا امدحه، ممتاز في كل شي تعامل، شرح و متساعد في المكتب حقه ويشرح لك بالتفصيل ما يسلك وحتى في الكلاس لو سألته بيرد عليك لين تفهم، اذا شفت اسمه وما نزلت عنده اي كورس حتى لو 101 المفروض تتحسف اسبوع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534406-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/musa-musa/81690/22", "user": "Ahmed1", "ts": 1653365306000, "tid": 81690, "pn": 22}}]}', 1653365306000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3388-chem201', 'stk-user3388', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f90836", "n": "د. عامر عدنان البطة", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : ورقه يعطيها الطلاب واخر الكلاس ياخذها\nطريقة الشرح :ممتاز جدا وعلى السبوره ميزة شرحه انه يبدا يعطيك امثله ويحلها ومن الامثله تفهم ويحط لك اكثر من مثال علشان يبين لك التركات والاختلافات بين المركبات يعني يعطيك الزبده بدون فلسفه\nالكويزات : حلوه جدا مو صعبه لو كنت فاهم معه بالشرح وحليت اسئلة الهومورك وصدقني اسئلة الهوموورك تعطيك سبعين الى ثمانين بالميه من اسئلة المياجر\nالمياجر: كومن ويركزون على اسئلة الهوومورك لدرجة بعضهن تجي كوبي بيس يعني نسخ ولصق\nالفاينلات : كومن ولو جابوا اختيارات صعبه الرتن احسن بكثير انا كذا نظرتي\nالقريد النهائي:A+++++++++++++++++ بصراحه اذا مانزلت عنده كورس واحد على الاقل من الكورسين حقات الاورقانيك فاتك الشي الكثير وراح تندم طول حياتك\n\nالصوت:ممتاز جدا متمكن من اللغه بشي عجيب\nإضافات : استفد من الدكتور بالاوفس اور حتى لو كانت اسئلتك تافهه فهو انسان حبوب ويشرح لك لين تدخل المعلومه في راسك\n\nملاحظة ترا كل الكلام حسب الكورس اللي اخذته معه chem201 وتمنيت انزل معه تو او تو بس مالقيته لكيشتر نزلت معه لاب وبصراحه اللاب من امتع اللابات وبسرعه يخلص وله طريقه ممتازه باللاب يعني دكتور مايتفوت ولو نزلت معه حرام تطلع بقريد اقل من بي بلص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p644123-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/90836/2", "user": "user3388", "ts": 1277502800000, "tid": 90836, "pn": 2}}]}', 1277502800000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-chem201', 'stk-guest', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f90836", "n": "د. عامر عدنان البطة", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 - 131\n\nالتحضير : ورقة تعدي ، يتأكد أن عدد الحاضرين يساوي العدد اللي في الورقة\nطريقة الشرح : شريح شريح شريح ، يكتب على السبورة و يجتهد أنه يوصل المعلومة ، بعد ميجر 2 صار يستعمل السلايدات\nالكويزات : اختبرنا 10 كويزات هذا السمستر كانت غالبا 7 أسئلة اختيارات و يكون أحيانا في سؤال او اثنين ريتين ، الدكتور يدعي أن أسئلته سهلة لكن الواقع أنها صعبة و مليانة تركات\nالمياجر: كومن، الجزء اللي يحطه عادي لا هو سهل و لا صعب\nالفاينلات : كومن\nالقريد النهائي: أعطيه a\nالصوت: واضح و الأكسنت ممتاز\nإضافات : الدكتور يدرس مواد الاورقانيك فقط ، صغير بالعمر نسبيا خريج جامعة كاليفورنيا في الدكتوراة ، متعاون جدا جدا في الاوفس أور و أيضا يرد على الأسئلة عبر الايميل في أي وقت ، الكلاس وورك كان الطلاب متقاربين فيه جدا و أعلى واحد أخذ 9.5 من 12 (6 كويزات + 3 حضور + 3 هومووركات)\n\nختاما أنصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312433-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/90836/10", "user": "Guest", "ts": 1388502477000, "tid": 90836, "pn": 10}}, {"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 - Lab & Lecture\n\nالتحضير\n: ورقة تمشي وتوقع عند اسمك.\n\nطريقة الشرح\n: يشرح سلايدات ويكتب على السبورة و شرحه مفهوم وواضح ومرتب.\n\nالكويزات\n: بعد كل شابتر فيه كويز (تقريباً كل أسبوع يعني) متوسطه الأسئلة بحكم انها تشبه أسئلة الأولد اقزامس.\n\nالواجبات\n: مخلي درجتها مع الحضور والغياب.\n\nالصوت\n: واضح ومفهوم جداً.\n\nالميجر\n: كومن كل دكتور يصحح سؤاله.\n\nاللاب\n: في البداية يشرح التجربة والخطوات والحسابات و اللاب كان معاه ممتع كان يدور في اللاب يشوف الطلاب أيش يسوون ويمزح معاهم , اللاب كان يطول غالباً بحكم تجارب الماده نفسها تطول. كل لاب فيه كويز بحكم انه ما فيه فاينل لاب.\n\nإضافات\n:\n\n- الدكتور مره متمكن من الماده وفاهمها وشريح مره لأن تخصصه عضويه , أصلاً يسمونه ملك الأورقانك 🤴.\n- أحياناً يسترسل في الشرح وما يحس بالوقت فيأخرنا دقيقيتين او 3 دقايق.\n- شبابي ينكت ويمزح في الكلاس ويغير جو.\n- يحشر للطلاب أحياناً ويسئلهم بس طبعاً من باب المزح 😁.\n- يفضل تكتب نوتات معاه لأنه مره بيساعدك على الفهم زياده.\n- عطانا كلاس أوف بعد الميجر.\n\nبالمختصر\n:\nالدكتور شريح ومره متمكن من الكورس وما غلط من سماه ملك الأورقانك , وكتعامل ممتاز , والكلاس معاه ممتع و حيفهمك الكورس مره , ولو رجعت بي الأيام ما راح أفكر بغيره و حنزل عنده أي كورس كمستري 🌹.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522237-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/20", "user": "Guest", "ts": 1590063802000, "tid": 99859, "pn": 20}}]}', 1388502477000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_3zzoz-chem201', 'stk-abu_3zzoz', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 201\nالتحضير :\nبالريبورت\nطريقة الشرح :\nجدا جدا رائعة , يشرح ع السبورة كل شي بعدين يكتب ويشرح البروسيجر خطوة خطوة\nالكويزات :\nمتوسطة مائلة الى الصعوبة\nالمياجر:\nالفاينلات :\nمافي فاينل لاب بالنسبة لل 201\nالقريد النهائي:\nA+\nالصوت:\nأوضح من الواضح\nإضافات :\nأفضل مدرس لاب مر علي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1021255-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/8", "user": "Abu_3zzoz", "ts": 1334244724000, "tid": 99859, "pn": 8}}]}', 1334244724000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salloum-chem201', 'stk-salloum', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست معه chem 201\nالتحضير :\nنهاية كل حصة\nطريقة الشرح :\nيفتح لك سلايدات خاصة فيه و يشرح عليها و يكتب اي شيء يحتاج توضيح\nالكويزات :\nبعد كل تشابتر ( اختبرنا 13 كويز في ترم 131 )\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nواضح جدا في اي مكان في الكلاس\nإضافات :\nأفضل مدرس كمستري مر علي إلى الآن ، شرح ممتاز و شخصية محبوبة و يهتم لمصلحة طلابه و لاتتردد تروح له الأوفس أورز بيساعدك في أي شيء تحتاجه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312021-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/11", "user": "Salloum", "ts": 1388424750000, "tid": 99859, "pn": 11}}]}', 1388424750000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-big_news-chem201', 'stk-big_news', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 (Lecture) - T202 (Online)\n\nالتحضير: بداية المحاضرة أو وسطها عن طريق رابط مايكروسوفت فورم وإذا حس أن الطلاب ساحبين يرجع يفتح التحضير.\nطريقة الشرح: يشرح من سلايداته ويكتب عليهم إذا احتاج. يعتمد على أسئلة الطلاب بشكل كبير وإذا الكل ساحب عليه وما يسأله يصير سريع بالمنهج.\nالكويزات: MCQ على البلاكبورد، متوسطة لصعبة.\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: C\nالصوت: واضح\nإضافات:\n\nسبب تقيمي C هو أن الكويزات والمياجر والفاينلات كانت كلها MCQ بدل الاختبارات الكتابية وهذا صعب المادة كثيرا لأن أسئلة الmechanisms حلها طويل وأي غلط بسيط ما يعطوك partial points على السؤال.\nالأسئلة الي يحلها في المحاضرة سطحية عكس أسئلة المياجر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533211-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/21", "user": "Big_News", "ts": 1640896061000, "tid": 99859, "pn": 21}}]}', 1640896061000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7903-chem201', 'stk-user7903', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f118613", "n": "Dr. Ahsan Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEm 201 Term 121\n\nمدرس حبيب وأخلاق طيبة …\nصوته واضح … يشرح على شرائح عرض …\n\nالكلاس وورك ماعطانا اياه في نهاية الفصل … مادري ليش\nمو متمكّن مره ولا هو سيّء مره …\n\nالتقييم : اعطيه B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1211442-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahsan-qureshi/118613/4", "user": "user7903", "ts": 1366133701000, "tid": 118613, "pn": 4}}]}', 1366133701000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali-che-chem201', 'stk-ali-che', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f118613", "n": "Dr. Ahsan Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 142\nCHEM201\nقبل ما اقيم الدكتور , الكورس ثقيل ويحتاج مجهود ومتابعه باستمرار\nفي بداية السمستر كان شرح الدكتور واضح جدا بس باخر 4 شباتر بدأ الرتم ينخفض\nيستخدم السلايدات والبورد ودائما يلخص الموضوع باخر خمس دقايق\nاختبرنا 11 كوز وحذف اسوأ 2 تقريبا\nمتساهل بالتحضير والصوت واضح\nميجر 1 يجي سهل والافرج مرتفع فوق 80\nميجر 2 يكون صعب والافرج ما يزيد عن 60\nالمياجر رتن ^\nالقريد النهائي B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424019-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahsan-qureshi/118613/9", "user": "Ali-CHE", "ts": 1439646587000, "tid": 118613, "pn": 9}}]}', 1439646587000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-chem201', 'stk-saleh_h', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f172598", "n": "Dr. Al-Harbi Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM201 - 211\n\nالتحضير : على حسب المزاج، ويمشي التأخير بعض الاحيان لكن بالمعقول والتحضير يكون اخر المحاضرة ينادي بالاسماء.\nطريقة الشرح : شرحه بكل صراحة سيء جدا وما يوصل المعلومة زين.\nالكويزات : كويزاته جحيم باختصار وتكون خارج وقت الكلاس (بعد العشاء) ومدتها ما بين ساعة - ساعة ونص وجدا صعبة صراحة.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D\nالصوت: واضح ولو ان انقليزيته تعبانة شوي\nإضافات : الدكنور حبيب لكن انتبه تفهي بوسط الشرح لانه بيستلمك أسئلة لين نهاية المحاضرة، طبعا انا كنت احد ضحايا الفهاوة وعلى عكس الاغلبية استلمني الى نهاية الترم حتى اني صرت معروف بين زملائي بلقب (ماركوفنيكوف) لانه اشغلني اسئلة فيها الين ما صرت احلم فيها وانا نايم… عموما اذا بتدرس عنده انصحك تغير اذا فيه فرصة او تخلي المادة سلف ستدي بحكم ان الاورقانيك يبيلها شغل ثقيل ومذاكرة أول بأول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533442-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-harbi-ahmed/172598/10", "user": "Saleh_H", "ts": 1642081501000, "tid": 172598, "pn": 10}}]}', 1642081501000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silence-chem201', 'stk-silence', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f172598", "n": "Dr. Al-Harbi Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM201 - T232\n\nالتحضير :\nمايحضر دايم, يحضر آخر المحاضرة على ورقة بالأسماء\n\nطريقة الشرح :\nالشرح في محتوى الميجر الأول كان سريع و ماكان فيه شي مفهوم, من بعد الميجر الأول تبدأ المادة فعليا و عقبها صار شرحه جيد, الدكتور يشرح لك بحيث تتمكن من حل الأسئلة بالأختبار فقط ولا الكونسبت انسى, يحل اولد اكزامز كثير و هذا شيء جدا يفيد, يشرح بطريقة فكاهية و دمه خفيف ينكت واجد, بغض النظر عن طريقة شرحه, اذا ركزت و انتبهت معه في مابعد الميجر الأول من الميتيريل راح يريحك كثير في المذاكرة\n\nالكويزات :\nكلها MCQ على البلاكبورد عن بعد (يطلب منكم نفنحون الكام) + من النوع الي تحل سؤال و ماتقدر ترجع له, تكون طويلة (مدتها ساعة و 15-25 سؤال للكويز) و ثقيلة نوعا ما لانها غالبا عبارة عن تشابترين و المادة مب خفيفة, مستواها من متوسطة الى صعبة, الشيء الايجابي هو ان الافرج يكون نازل ف يرفعكم بالنورم\n\nالمياجر:\nكزمن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nكلامه كله عربي و واضح\n\nإضافات :\nالدكتور جدا حبيب ياخذ و يعطي مع الطلاب و كأنهم اخوياه, بيئة الكلاس حلوة و غير أكاديمية لأنه حرفيا صار يمون على الطلاب و جميع انواع الحديث قابلة ل التناول, لكن فعلا بيئة حلوة و ممتعة و بنفس الوقت مب مضيعة وقت لأنك تطلع فاهم و مروق, متساهل في تأجيل مواعيد الكويزات و يشاوركم دايم قبل يحدد الموعد, بالنسبة لي من افضل الدكاترة الي نزلت عندهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538837-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-harbi-ahmed/172598/11", "user": "Silence", "ts": 1736383288885, "tid": 172598, "pn": 11}}]}', 1736383288885, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-woood-chem201', 'stk-woood', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 201 organic\nالتحضير : يمرر ورقة يعني يمديك تحضر خويك بالراحة\nطريقة الشرح : يشرح من السلايدات ويستخدم السبورة في كثير من الاحيان وشرحه جدا عادي\nالكويزات : متوسطة الى صعبة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: بتتعب على ما تتأقلم على لهجته\nإضافات : يوجد الكثير من هم افضل منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1447721-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/2", "user": "WoOoD", "ts": 1461929416000, "tid": 172599, "pn": 2}}]}', 1461929416000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem201', 'stk-user9305', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 201 (Organic Chemistry I) - Term 141 Lab\n\nطريقة الشرح:\nيكتب التجربة على السبورة بشكل منظم ويشرحها خطوة بخطوة.\n\nالصوت:\nواضح.\n\nإضافات:\n- متعاون في المختبر بشكل كبير، يهتم بأسئلة الطلاب بشكل كبير جداً ويجاوب عليهن بدون أي تململ او تضايق.\n\n- مشكلته الوحيدة انه يجاوب على السؤال ويشطح لمواضيع ثانية فتجده ياخذ 45 دقيقة للإجابة على سؤال لا يستحق اكثر من 10 دقائق. من أجل هذا لا تسأله حتى ينتهي من الشرح وبالتالي ما تأخر زملائك عن البدء بالتجربة.\n\n- يزعل من الشباب اللي ما يحضرون للكويزات، وبالذات اللي يخطئون في أسئلة تُعتبر بديهية في نظره، في البداية راح يعاتبهم لكن في نهاية الترم راح ينفجر في وجوههم فالحذر واجب 🚬.\n\nالقريد النهائي:\nB+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457736-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/5", "user": "user9305", "ts": 1474047066000, "tid": 172599, "pn": 5}}]}', 1474047066000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10520-chem201', 'stk-user10520', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\nحملة كتابة التقييمات\n\nالمادة:\nLab CHEM 201\nOrganic Chemistry - lab\n\nطريقة الشرح :\nيشرح خطوات التجربة المطلوبة عليك، يحاول يسهل التجربة قد ما يمكن\nطبيعة لابات الأورقانيك طويلة… كثير منها نطلع بدري واللاب اللي جنبنا ينقعون إلى 5.\nما يشرح كونسبت كثير، يشرح اللي تسويه وبس.\n\nالكويزات والهومووركات :\nكل لاب فيه هوموورك تجي وأنت حالّه\nالهوموورك يكون عن التجربة، المفترض تقرا التجربة من الكتاب وتحل الأسئلة\nلكن نصيحة/ وفّر وقت وجهد ذهني وابحث من قوقل مباشرة تجيك الإجابة أوضح وتفهم زين وتجيك الدرجة الزينة\nأحيانا يعطي كويزّات ويعلّمنا قبلها.\n\nالقريد النهائي :\nB+\n\nالصوت: وااضح\n\nإضافات :\nالدكتور جبّوب وينكّت\nتسأل سؤال بسيط يقعد يجاوب خمس ساعات !\nكان يدقق بأول الريبورتات، ثمين بدا يسلّك بالتصحيح.\n\nعموماً، بالنسبة لي كطالب يحب يجرب أشياء جديدة\nهذا الدكتور إضافة حليوة لحياتك الجامعية\nحليوة يعني مب زي كلاسات ختك 😆", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1464464-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/6", "user": "user10520", "ts": 1481694111000, "tid": 172599, "pn": 6}}]}', 1481694111000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-chem201', 'stk-khdsa2022', 'CHEM 201', 'doc', '{"docs": [{"id": "stk-dr-f176823", "n": "Dr. Jalilov Almaz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : JALILOV ALMAZ\nBY WHATSAPP\nالمادة: CHEM 201\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : متساهل جدا\nطريقة الشرح : يشرح بعدين يفتح السلايدات يشوف إذا في شيء نسى يشرحه ، شرحه ممتاز بس مايكفيك لازم ترجع تذاكر الكتاب\nالكويزات : كل خميس كويز من متوسطة الى صعبة\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت: ممتاز وواضح\nإضافات : الهوموركات بعد كل ميجر تحل الاسئلة اللي في السيلبس ، خذ افضل خمس كويزات من 12", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518846-chem201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jalilov-almaz/176823/6", "user": "Khdsa2022", "ts": 1578295850000, "tid": 176823, "pn": 6}}]}', 1578295850000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
